public class ActivityMonitoringController {
	private UserService userService;
	private ReportService reportService;
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public ActivityMonitoringController() {
		this.userService = new UserService();
		this.reportService = new ReportService();
	}
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public Map<String, Object> generateActivityMonitoring(
			Long userId,
			Map<String, Object> criteriaMonitoring
	) {
		// Implementation note for the English standalone variant.
		if (userId == null || criteriaMonitoring == null) {
			return null;
		}
		// Implementation note for the English standalone variant.
		if (!verifyOperatorAuthorization(userId)) {
			System.err.println("[ActivityMonitoringController] Access denied: user " + userId + " is not a municipal operator.");
			return null;
		}
		// Implementation note for the English standalone variant.
		validateCriteria(criteriaMonitoring);
		// Implementation note for the English standalone variant.
		String typeMonitoring = (String) criteriaMonitoring.get("typeMonitoring");
		if ("inProgress".equals(typeMonitoring)) {
			return processMonitoringInProgress(userId, criteriaMonitoring);
		} else if ("summaryArea".equals(typeMonitoring)) {
			return processAreaMonitoringSummary(userId, criteriaMonitoring);
		} else {
			return processGeneralMonitoring(userId, criteriaMonitoring);
		}
	}
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public boolean verifyOperatorAuthorization(Long userId) {
		if (userId == null) {
			return false;
		}
		// Implementation note for the English standalone variant.
		return userService.isMunicipalOperator(userId);
	}
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public void validateCriteria(Map<String, Object> criteriaMonitoring) {
		if (criteriaMonitoring == null) {
			throw new IllegalArgumentException("Monitoring criteria must not be null.");
		}
		Date dStart = (Date) criteriaMonitoring.get("dateStart");
		Date dEnd = (Date) criteriaMonitoring.get("dateEnd");
		Date oggi = new Date();
		if (dStart == null || dEnd == null) {
			throw new IllegalArgumentException("Enter both dates in dd-MM-yyyy format.");
		}
		// Implementation note for the English standalone variant.
		if (dStart.after(oggi)) {
			throw new IllegalArgumentException("Start date cannot be later than today.");
		}
		// Implementation note for the English standalone variant.
		if (dEnd.after(oggi)) {
			throw new IllegalArgumentException("End date cannot be in the future.");
		}
		// Implementation note for the English standalone variant.
		if (dStart.after(dEnd)) {
			throw new IllegalArgumentException("Start date must be on or before end date.");
		}
	}
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public Map<String, Object> processGeneralMonitoring(Long userId, Map<String, Object> criteria) {
		return reportService.generateMonitoringResults(userId, criteria);
	}
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public Map<String, Object> processMonitoringInProgress(Long userId, Map<String, Object> criteria) {
		return reportService.generateMonitoringResults(userId, criteria);
	}
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public Map<String, Object> processAreaMonitoringSummary(Long userId, Map<String, Object> criteria) {
		return reportService.generateMonitoringResults(userId, criteria);
	}
