public class ReportStatusUpdateController {
	private UserService userService;
	private ReportService reportService;
	private NotificationController notificationController;
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public ReportStatusUpdateController() {
		this.userService = new UserService();
		this.reportService = new ReportService();
		this.notificationController = new NotificationController();
	}
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public boolean registerStatusUpdate(
			Long userId,
			Long reportId
	) {
		if (userId == null) {
			throw new IllegalArgumentException("Please sign in.");
		}
		if (reportId == null) {
			throw new IllegalArgumentException("Select a report before confirming the update.");
		}
		if (!userService.isMunicipalOperator(userId)) {
			throw new IllegalArgumentException("Insufficient privileges. Only an operator can update the status.");
		}
		java.util.Map<String, Object> details = reportService.retrieveDetailsReport(userId, reportId);
		if (details == null || details.isEmpty()) {
			throw new IllegalArgumentException("Report not found.");
		}
		String currentStatus = (String) details.get("currentStatus");
		if ("resolved".equalsIgnoreCase(currentStatus)) {
			throw new IllegalArgumentException("A resolved and closed report cannot be changed.");
		}
		String newStatus = applyNewStatus(
				userId,
				reportId
		);
		if (isBlank(newStatus)) {
			return false;
		}
		/**
		 * Documents this component's behavior and responsibilities.
		 */
		requestNotification(
				reportId,
				newStatus
		);
		return true;
	}
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public String applyNewStatus(
			Long userId,
			Long reportId
	) {
		if (userId == null || reportId == null) {
			return null;
		}
		return reportService.updateReportStatus(
				userId,
				reportId
		);
	}
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	public void requestNotification(
			Long reportId,
			String newStatus
	) {
		if (reportId == null || isBlank(newStatus)) {
			return;
		}
		notificationController.verifyNotifiableStatus(
				reportId,
				newStatus
		);
	}
	/**
	 * Documents this component's behavior and responsibilities.
	 */
	private boolean isBlank(String value) {
		return value == null || value.trim().isEmpty();
	}
