        public Map<String, Object> generateMonitoringResults(
                Long userId,
                Map<String, Object> criteriaMonitoring
        ) {

            if (userId == null || criteriaMonitoring == null) {
                return null;
            }

            Map<String, Object> criteriaRicerca = new HashMap<>();

            Object dateStart = criteriaMonitoring.get("dateStart");
            Object dateEnd = criteriaMonitoring.get("dateEnd");
            Object category = criteriaMonitoring.get("category");
            Object municipalArea = criteriaMonitoring.get("location.municipalArea");
            Object currentStatus = criteriaMonitoring.get("currentStatusName");

            String typeMonitoring = extractString(
                    criteriaMonitoring.get("typeMonitoring")
            );

            if (category != null) {
                criteriaRicerca.put("category", category);
            }

            if (municipalArea != null && !isBlank(extractString(municipalArea))) {
                criteriaRicerca.put("location.municipalArea", municipalArea);
            }

            if (currentStatus != null && !isBlank(extractString(currentStatus))) {
                criteriaRicerca.put("currentStatusName", currentStatus);
            }

            List<Report> reports = persistenceService.findByFields(
                    Report.class,
                    criteriaRicerca
            );

            List<Report> reportsFiltrate = filterReportsByRange(
                    reports,
                    dateStart,
                    dateEnd
            );

            Map<String, Object> results = new HashMap<>();

            results.put("typeMonitoring", typeMonitoring);
            results.put("totalReports", countReports(reportsFiltrate));
            results.put("resolvedReports", countResolvedReports(reportsFiltrate));
            results.put("openReports", countOpenReports(reportsFiltrate));
            results.put("conteggioPerCategory", calculateCategoryDistribution(reportsFiltrate));

            if ("inProgress".equals(typeMonitoring)
                    || "summaryArea".equals(typeMonitoring)) {
                results.put("reportsRisultato", mapListReports(reportsFiltrate));
            } else {
                results.put("reportsRisultato", new java.util.ArrayList<Map<String, Object>>());
            }

            return results;
        }


